mapper.select:

WHERE r.product_id = #{productId}
  AND r.status = 'VISIBLE'
ORDER BY r.id DESC
LIMIT #{size} OFFSET #{offset}


WHERE r.status = 'VISIBLE'
ORDER BY r.id DESC
LIMIT #{limit}

mapper.update:
UPDATE reviews
   SET status = #{nextStatus}
 WHERE id = #{id}
   AND status = #{currentStatus}

mapper.select:
SELECT id, review_id, image_url, sort_order FROM review_images WHERE review_id IN
#{reviewId}
ORDER BY review_id, sort_order, id

mapper.update:
UPDATE review_replies
   SET admin_id = #{adminId},
       content = #{content}
 WHERE review_id = #{reviewId}

mapper.select:
SELECT id, review_id, admin_id, content, created_at, updated_at
  FROM review_replies
 WHERE review_id = #{reviewId}

SELECT COUNT(*)                                     AS review_count,
       COALESCE(ROUND(AVG(overall_rating), 1), 0)   AS average_rating
  FROM reviews
 WHERE status = 'VISIBLE'
   AND created_at >= #{from}
   AND created_at < #{to}

SELECT member_id AS memberId, COUNT(*) AS count FROM reviews WHERE member_id IN
#{memberId}
GROUP BY member_id
